function out = DiplayResBi(Res, background)% DiplayRes - 双向 cluster 检测 & 显示%%   out = DiplayRes(Res, [background])%% 输入:%   Res.ZSCi   - Z-transformed smooth classification image%   Res.tC     - Cluster 阈值%   Res.k      - 最小 cluster 大小%   Res.FWHM   - 平滑参数%   Res.p      - p 值%   [background] - (可选) 背景图像%% 输出:%   out{1} = 正向显著 cluster mask%   out{2} = 负向显著 cluster maskZSCi = Res.ZSCi;tC   = Res.tC;k    = Res.k;% ------------------------------------------------------------% 1. 阈值检测cCi_pos = (ZSCi >= tC);cCi_neg = (ZSCi <= -tC);[LabelClC_pos, nbClusterC_pos] = bwlabel(cCi_pos);[LabelClC_neg, nbClusterC_neg] = bwlabel(cCi_neg);out = cell(1,2);out{1} = zeros(size(ZSCi)); % positiveout{2} = zeros(size(ZSCi)); % negativeAllout = cell(1,1);Allout = zeros(size(ZSCi)); % ------------------------------------------------------------% 2. 应用 cluster 大小阈值for ii = 1:nbClusterC_pos    idx = find(LabelClC_pos == ii);    if numel(idx) >= k        out{1}(idx) = 1;        Allout(idx) = 1;    endendfor ii = 1:nbClusterC_neg    idx = find(LabelClC_neg == ii);    if numel(idx) >= k        out{2}(idx) = 1;        Allout(idx) = -1;    endend% ------------------------------------------------------------% 3. 打印结果fprintf('\nCluster Test Results (DiplayRes):\n');fprintf('\tSign\t size\t Zmax\tx\ty\n');fprintf('\t-------------------------------------\n');printClusterInfo(out{1}, ZSCi, '+');printClusterInfo(out{2}, ZSCi, '-');fprintf('\n');fprintf('p-value = [%.3f]\n',Res.p);fprintf('FWHM    = [%.1f]\n',Res.FWHM);fprintf('Minimum cluster size = %.1f\n',max(Res.k,0));% ------------------------------------------------------------% 4. 绘图figuretCi = Allout;%for ii = 1:2   % if ii == 1       % ss = 'Positive Clusters';        %tCi = out{1};   % else    %    ss = 'Negative Clusters';       % tCi = -out{2}; % 蓝色    %end    %subplot(1,2,ii)    %if ~exist('background','var')        %imagesc(tCi); axis image; axis off        %colormap([0 0 1; 1 1 1; 1 0 0]); % 蓝-白-红        %caxis([-1 1])        %title(ss);    %else        % normalize background        %bg = (background-min(background(:))) / ...             %(max(background(:))-min(background(:)));        bg = background/255*0.75;        cIma = repmat(bg,[1 1 3]);        cIma(:,:,1) = cIma(:,:,1) + (tCi>0); % 红色        cIma(:,:,3) = cIma(:,:,3)+ (tCi<0); % 蓝色        %cIma = cIma ./ max(cIma(:));        imagesc(cIma); axis square; axis off        %title(ss);   % endend% ============================================================% 辅助函数：打印 cluster 信息function printClusterInfo(mask, ZSCi, signFlag)[L, nC] = bwlabel(mask);for cc = 1:nC    idx = find(L == cc);    maxZ = max(abs(ZSCi(idx)));    [I,J] = ind2sub(size(L),idx);    yZ = round((max(I)+min(I))/2);    xZ = round((max(J)+min(J))/2);    fprintf('%c\t%d\t%.2f\t%d\t%d\n',signFlag,numel(idx),maxZ,xZ,yZ);endif nC==0    fprintf('\tno %s cluster reach significance\n', ...        iff(signFlag=='+','positive','negative'));endendfunction out = iff(cond,a,b)if cond, out=a; else, out=b; endend